const objects=[],orbitLines=[],labels=[];const sphere=new THREE.SphereGeometry(1,64,40);
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');const g=x.createRadialGradient(128,128,0,128,128,128);g.addColorStop(0,'rgba(255,220,150,1)');g.addColorStop(.2,'rgba(255,169,60,.5)');g.addColorStop(.45,'rgba(255,112,30,.12)');g.addColorStop(1,'rgba(255,90,10,0)');x.fillStyle=g;x.fillRect(0,0,256,256);return new THREE.CanvasTexture(c)}
