function atmosphere(body,color,size){const m=new THREE.ShaderMaterial({uniforms:{tint:{value:new THREE.Color(color)}},vertexShader:'varying vec3 vN; varying vec3 vP; void main(){vN=normalize(normalMatrix*normal);vec4 p=modelViewMatrix*vec4(position,1.0);vP=p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'uniform vec3 tint; varying vec3 vN; varying vec3 vP; void main(){float f=pow(1.0-abs(dot(normalize(vN),normalize(-vP))),3.0);gl_FragColor=vec4(tint,f*0.45);}',transparent:true,depthWrite:false,blending:THREE.AdditiveBlending});const a=new THREE.Mesh(sphere,m);a.scale.setScalar(size);body.add(a)}atmosphere(objects[3].group,0x459bff,1.18);atmosphere(objects[7].group,0x8edbdf,1.87);atmosphere(objects[8].group,0x466dff,1.83);
const ringCanvas=document.createElement('canvas');ringCanvas.width=1024;ringCanvas.height=2;const rx=ringCanvas.getContext('2d');for(let x=0;x<1024;x++){const a=.22+Math.random()*.6;rx.fillStyle=`rgba(205,187,148,${x>550&&x<585?.025:a})`;rx.fillRect(x,0,1,2)}const ringMap=new THREE.CanvasTexture(ringCanvas);const ringGeometry=new THREE.RingGeometry(3.3,5.7,192);const uv=ringGeometry.attributes.uv,pos=ringGeometry.attributes.position;for(let i=0;i<uv.count;i++){const radius=Math.hypot(pos.getX(i),pos.getY(i));uv.setXY(i,(radius-3.3)/2.4,.5)}const rings=new THREE.Mesh(ringGeometry,new THREE.MeshStandardMaterial({map:ringMap,side:THREE.DoubleSide,transparent:true,roughness:1,opacity:.9}));rings.rotation.x=-Math.PI/2+.45;objects[6].group.add(rings);
