let seed=71;function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646}
const starPositions=[],starColors=[];for(let i=0;i<6500;i++){const r=350+random()*400,theta=random()*Math.PI*2,y=random()*2-1,s=Math.sqrt(1-y*y);starPositions.push(r*s*Math.cos(theta),r*y,r*s*Math.sin(theta));const c=new THREE.Color().setHSL(.55+random()*.15,.08+random()*.25,.35+random()*.55);starColors.push(c.r,c.g,c.b)}const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));sg.setAttribute('color',new THREE.Float32BufferAttribute(starColors,3));scene.add(new THREE.Points(sg,new THREE.PointsMaterial({size:.65,vertexColors:true,transparent:true,opacity:.85,sizeAttenuation:true})));
const beltPositions=[];for(let i=0;i<2100;i++){const a=random()*Math.PI*2,r=27+random()*3.2;beltPositions.push(Math.cos(a)*r,(random()-.5)*.65,Math.sin(a)*r)}const bg=new THREE.BufferGeometry();bg.setAttribute('position',new THREE.Float32BufferAttribute(beltPositions,3));const belt=new THREE.Points(bg,new THREE.PointsMaterial({color:0x9e8b75,size:.065,transparent:true,opacity:.6}));scene.add(belt);
let selected=0,following=false,transition=null,paused=false,time=0,speed=1,showLabels=true;const lastTarget=new THREE.Vector3();
function select(i){selected=i;const d=data[i];$('#kind').textContent=d[6];$('#name').textContent=d[0];$('#number').textContent=i?String(i).padStart(2,'0'):'☉';$('#description').textContent=d[7];$('#facts').innerHTML=`<div><span>Diameter</span><strong>${d[8]}</strong></div><div><span>${i?'From the Sun':'Surface temperature'}</span><strong>${d[9]}</strong></div><div><span>${i?'Orbital period':'Age'}</span><strong>${d[10]}</strong></div>`;$('#focus').textContent=`↗  Explore ${i?d[0]:'the Sun'}`;[...$('#planets').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)});if(following)focus();}
function focus(){following=true;const body=objects[selected];const target=body.group.position.clone();const r=body.data[2];const offset=new THREE.Vector3(r*3,r*1.5,r*4.5);transition={target,position:target.clone().add(offset)};lastTarget.copy(target);controls.minDistance=r*1.5;}
$('#focus').onclick=focus;$('#overview').onclick=()=>{following=false;transition={target:new THREE.Vector3(4,0,0),position:new THREE.Vector3(48,66,100)};controls.minDistance=2};$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation')};$('#speed').oninput=e=>{speed=Number(e.target.value);$('#speed-value').textContent=`${speed}×`};$('#orbits').onclick=()=>{const visible=!orbitLines[0].visible;orbitLines.forEach(l=>l.visible=visible);$('#orbits').setAttribute('aria-pressed',visible)};$('#labels').onclick=()=>{showLabels=!showLabels;$('#labels').setAttribute('aria-pressed',showLabels)};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(objects.map(o=>o.mesh));if(hit.length){select(objects.findIndex(o=>o.mesh===hit[0].object));focus()}});
