function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);if(!paused)time+=dt*speed;objects.forEach((o,i)=>{const d=o.data;if(i){const a=o.angle+time*.12/d[4];o.group.position.set(Math.cos(a)*d[3],0,Math.sin(a)*d[3]);}if(!paused)o.mesh.rotation.y+=dt*speed*(i===2?-.03:.065);});moon.position.set(Math.cos(time*.8)*2.3,.2,Math.sin(time*.8)*2.3);if(following){const t=objects[selected].group.position;const delta=t.clone().sub(lastTarget);camera.position.add(delta);controls.target.add(delta);if(transition){transition.target.add(delta);transition.position.add(delta)}lastTarget.copy(t)}if(transition){const alpha=1-Math.exp(-dt*3);camera.position.lerp(transition.position,alpha);controls.target.lerp(transition.target,alpha);if(camera.position.distanceTo(transition.position)<.03)transition=null;}controls.update();objects.forEach((o,i)=>{projected.copy(o.group.position);projected.y+=o.data[2]+.7;projected.project(camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;labels[i].style.left=`${x}px`;labels[i].style.top=`${y}px`;labels[i].style.display=showLabels&&projected.z<1&&projected.z>-1&&x>0&&x<innerWidth&&y>90&&y<innerHeight-210?'block':'none';});$('#elapsed').textContent=`DAY ${String(Math.floor(time*7)).padStart(4,'0')}`;renderer.render(scene,camera)}animate();
